function [p_g, v_c, i_c] = mfun_gfm_standby_output(enable, p_g_in, v_c_in, i_c_in, fbk_in)
%MFUN_GFM_STANDBY_OUTPUT Block compute_standby_output of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN).
fbk = gfm_feedbacks_unpack(fbk_in);
% References of compute_output, or while the gates are blocked, of
% compute_standby_output
if enable > 0
    p_g = p_g_in;
    v_c = v_c_in;
    i_c = i_c_in;
else
    p_g = fbk.p_g;
    v_c = abs(fbk.v_c);
    i_c = [real(fbk.i_c); imag(fbk.i_c)];
end
end

function s = gfm_feedbacks_unpack(u)
%GFM_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c', complex(u(1), u(2)), ...
    'u_c', complex(u(3), u(4)), ...
    'u_c_zoh', complex(u(5), u(6)), ...
    'v_c', complex(u(7), u(8)), ...
    'u_g', complex(u(9), u(10)), ...
    'p_g', u(11), ...
    'q_g', u(12), ...
    'theta_c', u(13), ...
    'w_c', u(14));
end
